/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb']
def ballmask(fr):
    R,G,B = fr[...,0].astype(int), fr[...,1].astype(int), fr[...,2].astype(int)
    return (R>170)&(G>60)&(G<120)&(B<80)&(R-B>110)
def blockmask(fr):
    R,G,B = fr[...,0].astype(int), fr[...,1].astype(int), fr[...,2].astype(int)
    return (R>55)&(R<150)&(G>25)&(G<95)&(B>10)&(B<70)&(R>G+15)&(G>B+8)
for t in range(0,96,4):
    fr=d[t]
    bm=ballmask(fr); km=blockmask(fr)&~bm
    by,bx=np.nonzero(bm); ky,kx=np.nonzero(km)
    s=lambda a: (round(a.min(),1),round(a.max(),1),round(a.mean(),1)) if len(a) else None
    print(t,'ball x',s(bx),'block x',s(kx),'block y',s(ky) if len(ky) else None)
\""
